import math

def cosine_similarity(a, b):
    # already covered as comparing vectors in a shared space, generally in Sentence Embeddings
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    return dot / (norm_a * norm_b)

# already covered as a joint embedding space in this topic
image_embedding = {
    "cat_photo": [0.9, 0.1, 0.3],
    "dog_photo": [0.2, 0.8, 0.4],
}
text_embedding = {
    "a photo of a cat": [0.85, 0.15, 0.25],
    "a photo of a dog": [0.25, 0.75, 0.35],
}

print("Image-text similarity scores (already covered as a joint embedding space in this topic):\n")
for image_name, image_vec in image_embedding.items():
    for text_desc, text_vec in text_embedding.items():
        similarity = cosine_similarity(image_vec, text_vec)
        print(f"  {image_name} vs '{text_desc}': {similarity:.3f}")
